<script setup lang="ts">
import {computed,ref,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {useApplication} from '../../application';import Icon from '../../shared/Icon.vue';import GovernanceListFrame from './GovernanceListFrame.vue';import GovernanceDrawer from './GovernanceDrawer.vue';import FeedbackReviewPanel from './FeedbackReviewPanel.vue';import {useGovernanceList} from './useGovernanceList';import {localTime,stateLabels,usageLabels,feedbackLabels,type CorpusPage} from './workbench-types';
const app=useApplication(),route=useRoute(),router=useRouter(),list=useGovernanceList<CorpusPage>('corpus'),selected=ref<string|null>(null);
const row=computed(()=>list.page.value?.items.find(r=>r.id===selected.value)),canReview=computed(()=>!!row.value&&row.value.submitterId!==app.session.current.value?.actor.enterpriseId);
function open(id:string){selected.value=id;void router.replace({query:{...route.query,selected:id}});}
function close(){selected.value=null;void router.replace({query:{...route.query,selected:undefined}});}
watch(()=>route.query.selected,id=>{selected.value=typeof id==='string'?id:null;},{immediate:true});
</script>
<template><GovernanceListFrame title="语料管理" description="审阅六类结构化纠错，跟踪授权、来源版本与实际采用状态。" :counts="list.page.value?.counts??{}" :total="list.page.value?.total??null" :loading="list.loading.value" :error="list.error.value" v-model:query="list.query.value" :state="list.state()" :states="['PENDING','ACCEPTED','NEEDS_MORE','REJECTED']" :next-cursor="list.page.value?.nextCursor" :has-cursor="list.hasCursor()" @search="list.search" @filter="list.filter('state',$event)" @refresh="list.load" @next="list.next" @first="list.first"><template #actions><RouterLink class="btn" to="/feedback"><Icon name="message"/>我的反馈记录</RouterLink></template><template #filters><select class="select" aria-label="语料类型" :value="route.query.type??''" @change="list.filter('type',($event.target as HTMLSelectElement).value)"><option value="">全部类型</option><option v-for="(label,key) in feedbackLabels" :key="key" :value="key">{{label}}</option></select><select class="select" aria-label="语料使用状态" :value="route.query.usage??''" @change="list.filter('usage',($event.target as HTMLSelectElement).value)"><option value="">全部使用状态</option><option v-for="key in ['EFFECTIVE','PENDING_ADOPTION','NOT_APPLIED','WITHDRAWN','INVALID_SOURCE','LEGACY']" :key="key" :value="key">{{usageLabels[key]}}</option></select><input class="input" type="date" aria-label="语料提交起始日期" :value="route.query.from??''" @change="list.filter('from',($event.target as HTMLInputElement).value)"/><input class="input" type="date" aria-label="语料提交截止日期" :value="route.query.to??''" @change="list.filter('to',($event.target as HTMLInputElement).value)"/></template><div class="gov-table-wrap"><table class="gov-table"><thead><tr><th>纠错内容</th><th>类型</th><th>提交人</th><th>审核 / 使用</th><th>提交时间</th><th>操作</th></tr></thead><tbody><tr v-for="item in list.page.value?.items" :key="item.id"><td class="primary-cell"><button class="gov-link" @click="open(item.id)">{{item.suggestedValue??item.title}}</button><span class="sub-cell">{{item.originalValue?'原始值：'+item.originalValue:'历史未结构化记录'}}</span></td><td>{{feedbackLabels[item.feedbackType??'']??'历史反馈'}}</td><td>{{item.submitterName}}</td><td><span class="gov-tag" :data-state="item.state">{{stateLabels[item.state]}}</span><span class="sub-cell">{{usageLabels[item.usageState]}}</span></td><td>{{localTime(item.createdAt)}}</td><td><button class="gov-link" @click="open(item.id)">{{item.state==='PENDING'?'查看并审核':'查看详情'}}</button></td></tr></tbody></table></div><div v-if="!list.page.value?.items.length" class="gov-empty"><Icon name="message" :size="32"/><h3>当前筛选下没有反馈</h3><p>用户在会议中提交纠错后，记录会进入审核队列。</p></div></GovernanceListFrame><GovernanceDrawer v-if="selected" title="语料反馈详情" subtitle="审核结论与实际采用状态分别记录。" wide :busy="app.feedbackActions.busy.value" @close="close"><FeedbackReviewPanel :id="selected" :can-review="canReview" @changed="list.load"/></GovernanceDrawer></template>
